"use strict";
$(document).ready(function () {
    var modalEl = document.getElementById('orderStatusModal');
    if (modalEl) {
        var modal = new bootstrap.Modal(modalEl);
        var hintEl = document.getElementById('orderStatusModalHint');
        var reasonWrap = document.getElementById('orderStatusReasonWrap');
        var reasonSel = document.getElementById('orderStatusReason');
        var noteEl = document.getElementById('orderStatusNote');
        var confirmBtn = document.getElementById('orderStatusConfirm');
        var mode = 'advance';

        function open(m) {
            mode = m;
            reasonSel.value = '';
            noteEl.value = '';
            reasonSel.classList.remove('is-invalid');
            if (m === 'advance') {
                hintEl.textContent = 'Avançar a encomenda de Carregamento para Trânsito. A observação é opcional.';
                reasonWrap.style.display = 'none';
                confirmBtn.textContent = 'Confirmar';
                confirmBtn.className = 'btn btn-primary';
            } else {
                hintEl.textContent = 'Cancelar a encomenda? Seleccione o motivo (obrigatório).';
                reasonWrap.style.display = '';
                confirmBtn.textContent = 'Cancelar encomenda';
                confirmBtn.className = 'btn btn-danger';
            }
            modal.show();
        }

        $('#btnAdvance').on('click', function (e) { e.preventDefault(); open('advance'); });
        $('#btnCancelOrder').on('click', function (e) { e.preventDefault(); open('cancel'); });

        confirmBtn.addEventListener('click', function () {
            if (mode === 'cancel' && !reasonSel.value) {
                reasonSel.classList.add('is-invalid');
                reasonSel.focus();
                return;
            }
            reasonSel.classList.remove('is-invalid');
            modal.hide();
            var msg = mode === 'advance'
                ? 'Estado actualizado para Trânsito (protótipo)'
                : 'Encomenda cancelada (protótipo)';
            if (window.Swal) {
                Swal.mixin({
                    toast: true,
                    position: 'top-end',
                    showConfirmButton: false,
                    timer: 3000,
                    timerProgressBar: true
                }).fire({ icon: 'success', title: msg });
            } else {
                alert(msg);
            }
        });
    }

    // Mapa de acompanhamento Viana → Talatona (Leaflet + OSM)
    var mapEl = document.getElementById('orderTrackMap');
    if (mapEl && window.L) {
        var origin = [-8.9100, 13.3850];
        var dest = [-8.9180, 13.1840];
        var map = L.map(mapEl, { scrollWheelZoom: false }).setView([-8.914, 13.284], 12);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19,
            attribution: '&copy; OpenStreetMap'
        }).addTo(map);
        L.marker(origin).addTo(map).bindPopup('<b>Origem</b><br>Armazém Viana, Luanda');
        L.marker(dest).addTo(map).bindPopup('<b>Destino</b><br>Talatona, Luanda');
        L.polyline([origin, dest], { color: '#14b8a6', weight: 3, dashArray: '8 8' }).addTo(map);
        map.fitBounds(L.latLngBounds(origin, dest).pad(0.25));
        setTimeout(function () { map.invalidateSize(); }, 200);
    }
});
